(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8 + Math.cos((y+w1y)*0.02+t*0.15)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.3)*8 + Math.sin((x+w1x)*0.019-t*0.2)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [];
  for (let i = 0; i < 8; i++) {
    const a = i*0.7854 + t*(0.1+i*0.035);
    const r = 55 + Math.sin(t*0.2+i)*35 + i*18;
    src.push([240+Math.cos(a)*r+Math.sin(t*0.5+i*1.7)*45, 120+Math.sin(a)*r*0.7+Math.cos(t*0.4+i*2.1)*30, 0.04+(i%3)*0.025, 1.2+(i%4)*0.35]);
  }
  let aS=0,iS=0,hS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS += Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/8, inh=iS/8, harm=hS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.055+sy*0.018-t*0.9))/3;
  const moire = Math.sin(sx*0.075+t*0.5)*Math.sin(sy*0.075-t*0.3)*Math.sin((sx-sy)*0.055+t*0.7);
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
