  const r1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2 = Math.tanh((harm-act*0.5+moire*0.4+spiral*0.3)*1.8);
  const diff = Math.sin((r1+r2)*Math.PI*1.5+dist*0.03-t*0.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = r1*0.4+r2*0.3+diff*0.15+cell*0.15;
  const v = blend*0.5+0.5;
  const pal = [[4,10,48],[8,38,88],[12,72,122],[18,115,138],[38,155,125],[120,180,85],[195,180,55],[218,138,50],[212,92,60],[168,52,72],[105,28,60],[45,15,50],[4,10,48]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
